import {escapeHtml as esc} from './core.mjs';
export async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let b;try{b=await r.json();}catch{throw Error('Servidor indisponível.');}if(!r.ok)throw Object.assign(Error(b.error||'Falha na operação.'),{status:r.status});return b;}
export const formatPlanPrice=p=>p.priceCents===null||p.priceCents===undefined?'Preço em definição':(p.priceCents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})+' / mês';
export const subscriptionLabel=status=>({active:'Ativo',pending:'Aguardando ativação',canceled:'Cancelado',expired:'Expirado'})[status]||status;
export const send=(path,data,method='POST',options={})=>api(path,{...options,method,body:JSON.stringify(data)});
function showRecovery(root,code){root.innerHTML=`<main class="portal"><section class="card"><h1>Guarde seu código de recuperação.</h1><p>Este código permite recuperar sua conta se esquecer a senha. Ele será exibido somente agora. Guarde em um lugar seguro e não compartilhe.</p><code style="display:block;overflow-wrap:anywhere;padding:20px;background:#eef2e9">${esc(code)}</code><p>Ao recuperar a conta, o código será substituído por um novo.</p><button class="primary" id="recovery-continue">Já guardei. Continuar</button></section></main>`;root.querySelector('button').onclick=()=>location.reload();}
function recoveryForm(root){root.innerHTML=`<main class="portal"><section class="card portal-access"><div><h1>Recupere seu acesso.</h1><p>Use o código entregue ao criar sua conta. Sua senha será substituída e os dispositivos conectados sairão da conta.</p><a href="/">Voltar</a></div><form id="recovery-form"><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Código de recuperação<input name="recoveryCode" required minlength="64" maxlength="64" autocomplete="off"></label><label>Nova senha<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p role="alert" id="recovery-error"></p><button class="primary" type="submit">Recuperar conta</button></form></section></main>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const result=await send('recover',Object.fromEntries(new FormData(e.target)));showRecovery(root,result.recoveryCode);}catch(error){root.querySelector('#recovery-error').textContent=error.message;b.disabled=false;}};}
export async function startPlatform(){
 const root=document.querySelector('#app');let me;try{me=await api('me');}catch(e){if(e.status!==401){root.innerHTML=`<main class="portal"><h1>Mentra Life</h1><p>${esc(e.message)}</p><button id="retry-platform">Tentar novamente</button></main>`;root.querySelector('#retry-platform').onclick=()=>location.reload();return null;}}
 if(!me){await portal(root);return null;}
 const saved=await api('state');return {...me,...saved};
}
async function portal(root){
 const {plans}=await api('plans');let mode='login',selected=plans[0].id;
 function render(){root.innerHTML=`<div class="portal"><header class="portal-nav"><a href="/" class="portal-brand"><img src="assets/mentra-logo-original.png" alt="">mentra <small>LIFE</small></a><a id="open-auth" href="#acesso">Acessar minha conta →</a></header><main><section class="portal-hero"><div><p class="eyebrow">UM LUGAR PARA SUA VIDA</p><h1>Sua vida,<br><em>mais leve.</em></h1><p>Organize o dia, cuide do seu dinheiro e transforme ideias em próximos passos. Sua Mentra acompanha você.</p><a class="primary" href="#planos">Encontre seu plano →</a></div><img src="assets/mentra-face.png" alt="Mentra, sua assistente pessoal"></section><section class="portal-benefits">${[['Rotina com clareza','Agenda, tarefas e prioridades no seu ritmo.'],['Dinheiro organizado','Contas, lançamentos, compromissos e relatórios.'],['Ideias em movimento','Planos editáveis para começar e acompanhar.'],['Documentos à mão','Recibos em PDF e biblioteca de documentos.']].map(([t,d])=>`<article><h2>${t}</h2><p>${d}</p></article>`).join('')}</section><section id="planos"><p class="eyebrow">ESCOLHA SEU RITMO</p><h2>Três formas de ter a Mentra com você.</h2><p>Todos os planos incluem os módulos de organização. A capacidade de IA muda conforme o plano.</p><div class="portal-plans">${plans.map((p,i)=>`<article class="card ${i===1?'featured':''}"><p class="eyebrow">${i===1?'MAIS CONVERSAS':'MENTRA LIFE'}</p><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><strong>${formatPlanPrice(p)}</strong><ul><li>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA por mês</li><li>Agenda, tarefas e documentos</li><li>Finanças e recibos em PDF</li><li>Impulso e bem-estar</li><li>Painel individual</li></ul><button class="${i===1?'primary':'outline'}" data-plan="${p.id}">Escolher ${p.name}</button></article>`).join('')}</div><p>Cadastro disponível. A contratação e a ativação serão liberadas após a configuração dos pagamentos.</p></section><section class="portal-access card" id="acesso"><div><p class="eyebrow">SEU ESPAÇO</p><h2>${mode==='register'?'Comece com um pouco de clareza.':'Que bom ter você de volta.'}</h2><p>Seus dados ficam associados exclusivamente à sua conta.</p><button class="text-link" id="switch-auth">${mode==='register'?'Já tenho uma conta':'Quero criar uma conta'}</button></div><form id="auth-form">${mode==='register'?'<label>Seu nome<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label>E-mail<input name="email" type="email" autocomplete="email" required></label><label>Senha<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="12" maxlength="128" required><small>Use pelo menos 12 caracteres.</small></label>${mode==='register'?`<label>Seu plano<select name="plan">${plans.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${p.monthlyRequests} IA/mês</option>`).join('')}</select></label>`:''}<p id="auth-error" role="alert"></p><button class="primary" type="submit">${mode==='register'?'Criar minha conta':'Entrar'}</button></form></section></main><footer>Mentra Life · Um passo de cada vez.</footer></div>`;
 const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='text-link auth-recovery';recoveryButton.textContent='Recuperar acesso com meu código';recoveryButton.onclick=()=>recoveryForm(root);root.querySelector('#auth-form').append(recoveryButton);
 root.querySelector('#open-auth').onclick=e=>{e.preventDefault();mode='login';render();root.querySelector('#acesso').scrollIntoView({block:'start'});};
 root.querySelector('#switch-auth').onclick=()=>{mode=mode==='register'?'login':'register';render();root.querySelector('#acesso').scrollIntoView({block:'start'});};
 root.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{selected=b.dataset.plan;mode='register';render();root.querySelector('#acesso').scrollIntoView({behavior:'smooth'});});
 root.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await send(mode==='register'?'register':'login',Object.fromEntries(new FormData(e.target)));if(result.recoveryCode){showRecovery(root,result.recoveryCode);return;}location.reload();}catch(error){root.querySelector('#auth-error').textContent=error.message;button.disabled=false;}};
 }render();
}
export function accountMarkup(platform,preferences=''){return `<div class="page-heading"><div><p class="eyebrow">MEU ESPAÇO</p><h1>Seu jeito de seguir em frente.</h1><p class="subtitle">${esc(platform.user.name)} · ${esc(platform.user.email)}</p></div></div><div class="account-layout"><div class="account-main">${preferences}<section class="card account-security"><div class="section-head"><div><span class="eyebrow">ACESSO E PRIVACIDADE</span><h2>Segurança da conta</h2></div></div><details class="account-disclosure"><summary><span>Alterar senha<small>Proteja o acesso à sua conta.</small></span><span aria-hidden="true">＋</span></summary><form id="platform-password" class="form-stack"><label>Senha atual<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nova senha<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="form-help">Use de 12 a 128 caracteres. Todos os dispositivos serão desconectados e seus links privados serão revogados.</p><button class="primary" type="submit">Salvar nova senha e sair</button></form></details><details class="account-disclosure account-danger"><summary><span>Excluir minha conta<small>Exclusão definitiva dos dados da conta.</small></span><span aria-hidden="true">＋</span></summary><p>Esta ação é permanente. Assinaturas ativas precisam ser canceladas antes.</p><form id="platform-delete" class="form-stack"><label>Confirme sua senha<input name="password" type="password" autocomplete="current-password" required></label><label class="check-field"><input type="checkbox" name="confirmed" required><span>Entendo que todos os meus dados serão excluídos.</span></label><button class="outline danger" type="submit">Excluir conta permanentemente</button></form></details><p id="account-error" role="alert" class="form-error"></p></section></div><aside class="account-aside"><section class="card"><span class="eyebrow">SUA ASSINATURA</span><h2>${esc(platform.plans?.find(p=>p.id===platform.subscription.plan)?.name||platform.subscription.plan)}</h2><p>${esc(subscriptionLabel(platform.subscription.status))}</p><a class="outline full" href="#/planos">Ver meus planos</a></section><section class="card account-backup"><span class="eyebrow">CONTROLE DOS SEUS DADOS</span><h2>Sua cópia, com você</h2><p>Baixe uma cópia da sua organização para restaurar ou exporte todos os dados da conta.</p><button class="primary full" data-account="backup">Baixar cópia para restauração</button><button class="outline full" data-account="export">Exportar meus dados</button><p class="form-help">A exportação completa inclui o histórico das integrações. A cópia para restauração contém somente sua organização e seus originais.</p><details class="account-disclosure"><summary><span>Restaurar uma cópia</span><span aria-hidden="true">＋</span></summary><label class="restore-upload">Selecionar arquivo JSON<input type="file" data-restore accept=".json,application/json"></label><p class="form-help">Você verá as diferenças antes de confirmar. Assinatura e credenciais não são restauradas.</p></details></section></aside></div>`;}
export function plansMarkup(subscription,plans=[],usage={}){const current=plans.find(p=>p.id===subscription.plan);return `<div class="page-heading"><div><p class="eyebrow">ASSINATURA</p><h1>Seu plano, no seu ritmo.</h1><p>${esc(current?.name||subscription.plan)} · ${esc(subscriptionLabel(subscription.status))}</p>${usage.month?`<p>${Number(usage.requests||0).toLocaleString('pt-BR')} de ${Number(current?.monthlyRequests||0).toLocaleString('pt-BR')} mensagens usadas em ${esc(usage.month)}. O ciclo de uso segue o mês em UTC.</p>`:''}</div></div><div class="portal-plans">${plans.map(p=>`<section class="card ${p.id===subscription.plan?'plan-selected':''}"><h2>${esc(p.name)}</h2><strong>${formatPlanPrice(p)}</strong><p>${esc(p.description)}</p><p>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA/mês</p><p>Rotina, finanças, documentos, Impulso e bem-estar.</p><button class="${p.id===subscription.plan?'outline':'primary'}" aria-pressed="${p.id===subscription.plan}" data-platform-plan="${p.id}" ${subscription.status==='active'?'disabled':''}>${p.id===subscription.plan?'Plano selecionado':'Selecionar'}</button></section>`).join('')}</div><p class="notice">Os pagamentos serão disponibilizados após a configuração do gateway. Selecionar um plano não gera cobrança nem ativa uma assinatura.</p>`;}
